def chunk_fixed_ops(nl):
    """24-bit chunk extraction and zero branches of a plane with nl live lanes (zeros above): first chunk and top chunk one operation"""
    nch = (nl + 23) // 24
    ops = 0
    for c in range(nch):
        ops += (0 if nch == 1 else 1 if c in (0, nch - 1) else 2) + 1
    return ops
