def scan_bound_ok():
    """for every class size f <= 3600: the executed fibre tests, lane masks and chunk scans of its b = ceil(f/256) batches, the sum of
    W6_OPS + [nl < 256] + chunk_fixed_ops(nl), are at most (W6_OPS - 1) b + f/8 + 23/8 (a full batch costs W6_OPS + 31 = (W6_OPS - 1) + 256/8;
    the last batch at most W6_OPS + 1 + nl/8 + 7/8 since chunk_fixed_ops(nl) <= nl/8 + 7/8 for 1 <= nl <= 256)"""
    for f in range(1, 3601):
        b = (f + 255) // 256
        nls = [256] * (b - 1) + [f - 256 * (b - 1)]
        if sum((W6_OPS + (nl < 256) + chunk_fixed_ops(nl) for nl in nls)) > (W6_OPS - 1) * b + Fr(f, 8) + Fr(23, 8):
            return False
    return True
